// Levels stored as 0,1,2 (= 0, 1/2, 1). Column arrays top->bottom.
const RULES = {
  none: (col, u) => {},
  // single upward pass, each box pours as much as fits into the one below, unconditional
  passAlways: (col, u) => { for (let i = u - 1; i >= 0; i--) pour(col, i); },
  // upward pass continues only while the box below became empty before pour
  passIfEmptied: (col, u) => { let i = u; while (i > 0 && col[i] === 0) { pour(col, i - 1); i--; } },
  // triggered only if a FULL box emptied; then single pass while emptied
  fullTrigShift: (col, u, s) => { if (s === 2 && col[u] === 0) { let i = u; while (i > 0 && col[i] === 0) { pour(col, i - 1); i--; } } },
  // triggered only if FULL box emptied; then unconditional single pass
  fullTrigPass: (col, u, s) => { if (s === 2 && col[u] === 0) { for (let i = u - 1; i >= 0; i--) pour(col, i); } },
  // triggered only if a FULL box emptied; contiguous stack above compacts fully
  fullTrigCompact: (col, u, s) => { if (s === 2 && col[u] === 0) compact(col, u); },
  // triggered if box emptied (any); compaction
  emptiedCompact: (col, u, s) => { if (col[u] === 0) compact(col, u); },
  // always compaction of contiguous stack above
  alwaysCompact: (col, u, s) => { compact(col, u); },
};
function pour(col, i) { // box i pours into i+1
  const p = Math.min(col[i], 2 - col[i + 1]); col[i] -= p; col[i + 1] += p; return p;
}
function compact(col, u) {
  // contiguous non-empty stack directly above u
  let top = u; while (top > 0 && col[top - 1] > 0) top--;
  let total = 0; for (let i = top; i <= u; i++) { total += col[i]; col[i] = 0; }
  for (let i = u; i >= top && total > 0; i--) { const t = Math.min(2, total); col[i] = t; total -= t; }
}
// vertical action on column at gate below box u (u = n-1 => bottom gate to outside)
function vert(col, u, rule) {
  const n = col.length, c = col.slice(); const s = c[u];
  if (u === n - 1) c[u] = 0; else { const p = Math.min(c[u], 2 - c[u + 1]); c[u] -= p; c[u + 1] += p; }
  RULES[rule](c, u, s);
  const s2 = c[u];
  return { col: c, cost: 1 + 2 * (s + s2), changed: c.some((v, i) => v !== col[i]) };
}
function key(L, R) { return L.join('') + '|' + R.join(''); }
function dijkstra(L0, R0, rule, allowSide = true) {
  const n = L0.length; const dist = new Map(); const pq = [[0, L0, R0, []]];
  while (pq.length) {
    pq.sort((a, b) => a[0] - b[0]); const [d, L, R, path] = pq.shift(); const k = key(L, R);
    if (dist.has(k)) continue; dist.set(k, d);
    if (L.every(v => !v) && R.every(v => !v)) return { cost: d, path };
    for (let u = 0; u < n; u++) {
      for (const side of [0, 1]) {
        const col = side ? R : L; const r = vert(col, u, rule); if (!r.changed) continue;
        const nL = side ? L : r.col, nR = side ? r.col : R;
        if (!dist.has(key(nL, nR))) pq.push([d + r.cost, nL, nR, [...path, `${side ? 'R' : 'L'}v${u}:${r.cost}`]]);
      }
      if (allowSide && ((L[u] === 2 && R[u] === 0) || (L[u] === 0 && R[u] === 2))) {
        const nL = L.slice(), nR = R.slice(); nL[u] = 1; nR[u] = 1;
        if (!dist.has(key(nL, nR))) pq.push([d + 1, nL, nR, [...path, `s${u}:1`]]);
      }
    }
  }
  return null;
}
// does an ordered cost sequence exist that empties a single column?
function seqExists(col, seq, rule) {
  if (!seq.length) return col.every(v => !v);
  for (let u = 0; u < col.length; u++) { const r = vert(col, u, rule); if (r.changed && r.cost === seq[0] && seqExists(r.col, seq.slice(1), rule)) return true; }
  return false;
}
const L = [2, 0, 0, 2], R = [0, 2, 2, 0];
for (const rule of Object.keys(RULES)) {
  const opt = dijkstra(L, R, rule), noSide = dijkstra(L, R, rule, false);
  const c3 = [2, 1, 1, 2], c1 = [0, 1, 1, 0];
  console.log(rule.padEnd(16), 'opt', opt.cost, '| vertical-only', noSide.cost,
    '| L[5,5,9,5]', seqExists(L, [5, 5, 9, 5], rule), 'R[9,9,5]', seqExists(R, [9, 9, 5], rule),
    '| [7,9,9,5]', seqExists(c3, [7, 9, 9, 5], rule), '[3,5,9,9,5]', seqExists(c3, [3, 5, 9, 9, 5], rule), '[3,5,5]', seqExists(c1, [3, 5, 5], rule));
  console.log('   ', opt.path.join(' '));
}
EOF
