// Heuristic functions h(n): lower bounds on the remaining cost to reach "no sand anywhere".
// All values are in the same integer units as the action costs.

import { LEVEL, MAT, SAND, WATER, EMPTY, CONCRETE } from './model.js';

/** h = 0. Turns A* into uniform-cost search. */
function zero() { return 0; }

/**
 * Sand-volume bound.
 *
 * Sand only leaves through an outlet (or by setting into concrete). An outlet action that removes
 * s units costs at least 1 + 4s and removes at most one unit, so with T units of sand left the
 * outlets alone cost at least 4T + ceil(T).
 *
 * With water in the grid, a box of sand can instead be turned into concrete for `penalty`; one
 * concrete box absorbs at most one unit. For penalty >= 5 the bound above still holds; for a
 * cheaper penalty we fall back to T * min(5, penalty).
 */
function volume(model, cells) {
  let t = 0; // half-units of sand
  let water = false;
  for (let i = 0; i < cells.length; i++) {
    const m = MAT[cells[i]];
    if (m === SAND) t += LEVEL[cells[i]];
    else if (m === WATER) water = true;
  }
  if (water && model.concretePenalty < 5) return (t / 2) * Math.max(0, model.concretePenalty);
  return 2 * t + Math.ceil(t / 2);
}

/**
 * Volume + gap bound (sand-only grids).
 *
 * Take an empty box that has sand somewhere above it in the same column. Some of that sand must
 * eventually cross the gate on top of the empty box. The first crossing is either a paid action
 * on that very gate (cost >= 3), or a free ride in a pile collapse — which needs the empty box to
 * hold sand first, and without crossing the gate that can only come from its side gate (cost 1).
 * Either way at least 1 is paid by a non-outlet action that is specific to this box, so every
 * such box adds 1 on top of the volume bound.
 *
 * With water or concrete in the grid the argument no longer holds, so the gap term is dropped.
 */
function gap(model, cells) {
  let gaps = 0;
  for (let col = 0; col < 2; col++) {
    let sandAbove = false;
    for (let i = col; i < cells.length; i += 2) {
      const c = cells[i];
      if (c === EMPTY) { if (sandAbove) gaps++; } else if (MAT[c] === SAND) sandAbove = true;
      else if (MAT[c] === WATER || c === CONCRETE) return volume(model, cells);
    }
  }
  return volume(model, cells) + gaps;
}

export const HEURISTICS = Object.freeze({
  gap: { name: 'Volume + gaps', short: 'h₂', fn: gap, note: 'Sand volume plus one per empty box below sand. Admissible and consistent.' },
  volume: { name: 'Sand volume', short: 'h₁', fn: volume, note: '4T + ⌈T⌉ for T units of sand left. Admissible and consistent.' },
  zero: { name: 'Zero', short: 'h₀', fn: zero, note: 'No information: A* behaves exactly like uniform-cost search.' },
});

