// Sand Boxes — environment model (state, physics, actions, cost).
//
// The grid has `rows` rows and 2 columns. Cell index = row * 2 + col, row 0 is the top.
// Every cell holds one of six codes. Levels are stored in half-units (0, 1, 2 = 0, 1/2, 1).

export const EMPTY = 0;
export const SAND_HALF = 1;
export const SAND_FULL = 2;
export const WATER_HALF = 3;
export const WATER_FULL = 4;
export const CONCRETE = 5;

export const NONE = 0;
export const SAND = 1;
export const WATER = 2;
export const SOLID = 3;

/** Fill level of each cell code, in half-units. Concrete always fills its box. */
export const LEVEL = Object.freeze([0, 1, 2, 1, 2, 2]);
/** Material of each cell code. */
export const MAT = Object.freeze([NONE, SAND, SAND, WATER, WATER, SOLID]);

const CODE = [[0, 0, 0], [0, SAND_HALF, SAND_FULL], [0, WATER_HALF, WATER_FULL]];
export const cellCode = (mat, level) => (level === 0 ? EMPTY : CODE[mat][level]);

export const CELL_NAMES = ['empty', '½ sand', 'full sand', '½ water', 'full water', 'concrete'];

/**
 * What happens to the sand resting above a box that has just lost sand.
 *  - collapse: when a FULL box drains completely (a whole unit drops), the pile resting on it
 *    loses its support and the contiguous run of non-empty boxes above settles down.
 *    This is the rule that reproduces every worked number given with the assignment.
 *  - always:   the pile above settles after any downward flow, however small.
 *  - none:     nothing moves except the two boxes joined by the opened gate.
 */
export const CHAIN_MODES = Object.freeze({
  collapse: 'Pile collapse (default)',
  always: 'Always settle',
  none: 'No chain reaction',
});

/** Initial-state probabilities from the assignment (sand only) and a default mix with water. */
export const PROBS_SAND = Object.freeze({ empty: 0.5, sandHalf: 0.2, sandFull: 0.3, waterHalf: 0, waterFull: 0 });
export const PROBS_WATER = Object.freeze({ empty: 0.4, sandHalf: 0.15, sandFull: 0.2, waterHalf: 0.1, waterFull: 0.15 });

export class Sandbox {
  /**
   * @param {{rows?: number, chain?: 'collapse'|'always'|'none', concretePenalty?: number}} [opts]
   */
  constructor({ rows = 5, chain = 'collapse', concretePenalty = 10 } = {}) {
    if (!(rows >= 1 && rows <= 12)) throw new RangeError('rows must be between 1 and 12');
    if (!(chain in CHAIN_MODES)) throw new RangeError(`unknown chain mode: ${chain}`);
    this.rows = rows;
    this.size = rows * 2;
    this.chain = chain;
    this.concretePenalty = concretePenalty;

    /** Action list. Type 'b' = side gate of a row, type 'a' = top-down gate under a box. */
    this.actions = [];
    for (let r = 0; r < rows; r++) {
      this.actions.push({ id: r, type: 'b', row: r, label: `Side gate, row ${r + 1}`, short: `S${r + 1}` });
    }
    for (let c = 0; c < 2; c++) {
      for (let r = 0; r < rows; r++) {
        const outlet = r === rows - 1;
        const side = c === 0 ? 'Left' : 'Right';
        this.actions.push({
          id: rows + c * rows + r,
          type: 'a',
          col: c,
          row: r,
          outlet,
          label: outlet ? `${side} outlet (row ${r + 1})` : `${side} gate ${r + 1}→${r + 2}`,
          short: `${side[0]}${r + 1}${outlet ? '⤓' : '↓'}`,
        });
      }
    }
  }

  sideAction(row) { return row; }
  verticalAction(col, row) { return this.rows + col * this.rows + row; }

  // ---------------------------------------------------------------- encoding

  /** Pack a cell array into one number (base 6, exact up to 20 cells). */
  encode(cells) {
    let key = 0;
    for (let i = this.size - 1; i >= 0; i--) key = key * 6 + cells[i];
    return key;
  }

  decode(key) {
    const cells = new Uint8Array(this.size);
    for (let i = 0; i < this.size; i++) {
      cells[i] = key % 6;
      key = Math.floor(key / 6);
    }
    return cells;
  }

  /** Goal: no box contains sand (water and concrete may remain). */
  isGoal(cells) {
    for (let i = 0; i < this.size; i++) if (MAT[cells[i]] === SAND) return false;
    return true;
  }

  // ------------------------------------------------------------------ physics

  /**
   * Open one gate.
   * @param {Uint8Array} cells   state before the action (not modified)
   * @param {number} id          action id
   * @param {Array|null} events  if given, receives one entry per elementary flow, for animation
   * @returns {null | {cells: Uint8Array, cost: number, concrete: number, s: number, s2: number}}
   *          null when the gate would open on nothing (no sand or water moves).
   */
  apply(cells, id, events = null) {
    const act = this.actions[id];
    return act.type === 'b' ? this.#side(cells, act.row, events) : this.#vertical(cells, act.col, act.row, events);
  }

  /** Side gate: a full box levels with an empty neighbour, or spills into a half box of the other material. */
  #side(cells, row, events) {
    const i = row * 2;
    const j = i + 1;
    const a = cells[i];
    const b = cells[j];
    const ma = MAT[a];
    const mb = MAT[b];
    if (ma === SOLID || mb === SOLID) return null;
    const la = LEVEL[a];
    const lb = LEVEL[b];
    let from;
    let to;
    if (la === 2 && lb < 2) { from = i; to = j; } else if (lb === 2 && la < 2) { from = j; to = i; } else return null;
    const mf = MAT[cells[from]];
    const lt = LEVEL[cells[to]];
    const mt = MAT[cells[to]];
    let concrete = 0;
    const out = cells.slice();
    if (lt === 0) {
      out[from] = cellCode(mf, 1);
      out[to] = cellCode(mf, 1);
    } else if (mt !== mf) {
      // full box of one material pushes into a half box of the other: they set into concrete
      out[from] = cellCode(mf, 1);
      out[to] = CONCRETE;
      concrete = 1;
    } else {
      return null; // same material, 1 and 1/2: the levels 3/4 + 3/4 are not allowed, gate stays shut
    }
    if (events) events.push({ kind: 'side', from, to, amount: 1, mat: mf, concrete: concrete === 1, chain: false, cells: out.slice() });
    return { cells: out, cost: 1 + concrete * this.concretePenalty, concrete, s: 0, s2: 0 };
  }

  /** Top-down gate under box (row, col). The last row's gate is the outlet. */
  #vertical(cells, col, row, events) {
    const u = row * 2 + col;
    const cu = cells[u];
    const lu = LEVEL[cu];
    if (lu === 0 || cu === CONCRETE) return null;
    const out = cells.slice();
    const tally = { concrete: 0 };
    let moved;
    if (row === this.rows - 1) {
      out[u] = EMPTY;
      moved = lu;
      if (events) events.push({ kind: 'out', from: u, to: -1, amount: lu, mat: MAT[cu], concrete: false, chain: false, cells: out.slice() });
    } else {
      moved = this.#pour(out, u, u + 2, tally, events, false);
      if (moved === 0) return null;
    }

    const trigger =
      this.chain === 'collapse' ? lu === 2 && out[u] === EMPTY :
      this.chain === 'always' ? moved > 0 :
      false;
    if (trigger) this.#settle(out, col, row, tally, events);

    const s2 = LEVEL[out[u]];
    return {
      cells: out,
      cost: 1 + 2 * (lu + s2) + tally.concrete * this.concretePenalty, // 1 + 4 (s + s') with s in units
      concrete: tally.concrete,
      s: lu,
      s2,
    };
  }

  /** Let box `a` flow into the box `b` right below it. Returns the amount moved (half-units). */
  #pour(out, a, b, tally, events, chain) {
    const ca = out[a];
    const la = LEVEL[ca];
    if (la === 0 || ca === CONCRETE) return 0;
    const cb = out[b];
    if (cb === CONCRETE) return 0;
    const lb = LEVEL[cb];
    const p = Math.min(la, 2 - lb);
    if (p === 0) return 0;
    const ma = MAT[ca];
    out[a] = cellCode(ma, la - p);
    const reacts = lb > 0 && MAT[cb] !== ma;
    if (reacts) {
      out[b] = CONCRETE;
      tally.concrete++;
    } else {
      out[b] = cellCode(ma, lb + p);
    }
    if (events) events.push({ kind: 'pour', from: a, to: b, amount: p, mat: ma, concrete: reacts, chain, cells: out.slice() });
    return p;
  }

  /** The contiguous pile directly above `row` settles down under gravity. */
  #settle(out, col, row, tally, events) {
    let top = row;
    while (top > 0) {
      const c = out[(top - 1) * 2 + col];
      if (c === EMPTY || c === CONCRETE) break;
      top--;
    }
    let moved = true;
    while (moved) {
      moved = false;
      for (let r = row - 1; r >= top; r--) {
        if (this.#pour(out, r * 2 + col, (r + 1) * 2 + col, tally, events, true) > 0) moved = true;
      }
    }
  }

  /** All state-changing actions from `cells`: [{a, s, c}] with s the encoded successor. */
  successors(cells) {
    const list = [];
    for (let id = 0; id < this.actions.length; id++) {
      const r = this.apply(cells, id);
      if (r) list.push({ a: id, s: this.encode(r.cells), c: r.cost });
    }
    return list;
  }

  // ------------------------------------------------------------------ helpers

  /** Total sand in the grid, in half-units. */
  sand(cells) {
    let t = 0;
    for (let i = 0; i < this.size; i++) if (MAT[cells[i]] === SAND) t += LEVEL[cells[i]];
    return t;
  }

  count(cells, mat) {
    let n = 0;
    for (let i = 0; i < this.size; i++) if (MAT[cells[i]] === mat) n++;
    return n;
  }

  empty() { return new Uint8Array(this.size); }

  /** Random initial state, each cell drawn independently. */
  random(probs = PROBS_SAND, rng = Math.random) {
    const cells = new Uint8Array(this.size);
    const order = [[EMPTY, probs.empty], [SAND_HALF, probs.sandHalf], [SAND_FULL, probs.sandFull], [WATER_HALF, probs.waterHalf || 0], [WATER_FULL, probs.waterFull || 0]];
    const total = order.reduce((s, [, p]) => s + p, 0) || 1;
    for (let i = 0; i < this.size; i++) {
      let x = rng() * total;
      let pick = EMPTY;
      for (const [codeValue, p] of order) {
        if (x < p) { pick = codeValue; break; }
        x -= p;
      }
      cells[i] = pick;
    }
    return cells;
  }
}

// ------------------------------------------------------------------- text I/O

const TOKENS = new Map([
  ['0', EMPTY], ['.', EMPTY], ['_', EMPTY],
  ['½', SAND_HALF], ['0.5', SAND_HALF], ['.5', SAND_HALF], ['1/2', SAND_HALF], ['h', SAND_HALF],
  ['1', SAND_FULL],
  ['w', WATER_HALF], ['W', WATER_FULL],
  ['#', CONCRETE], ['C', CONCRETE],
]);
const GLYPH = ['0', '½', '1', 'w', 'W', '#'];

/** Parse "1 0 / 0 1 / ½ W" (rows separated by newlines or '/'). */
export function parseGrid(text) {
  const rows = text.split(/[\n/]+/).map((l) => l.trim()).filter(Boolean).map((l) => l.split(/[\s,]+/));
  const cells = new Uint8Array(rows.length * 2);
  rows.forEach((tokens, r) => {
    if (tokens.length !== 2) throw new SyntaxError(`row ${r + 1} must have exactly 2 cells`);
    tokens.forEach((t, c) => {
      if (!TOKENS.has(t)) throw new SyntaxError(`unknown cell "${t}" (use 0, ½, 1, w, W, #)`);
      cells[r * 2 + c] = TOKENS.get(t);
    });
  });
  return cells;
}

export function formatGrid(cells, sep = '\n') {
  const lines = [];
  for (let i = 0; i < cells.length; i += 2) lines.push(`${GLYPH[cells[i]]} ${GLYPH[cells[i + 1]]}`);
  return lines.join(sep);
}

/** Small deterministic PRNG (mulberry32) so experiments are reproducible. */
export function seededRng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** The 4x2 example given with the assignment. */
export const PROFESSOR_EXAMPLE = '1 0 / 0 1 / 0 1 / 1 0';

// Heuristic functions h(n): lower bounds on the remaining cost to reach "no sand anywhere".
// All values are in the same integer units as the action costs.

import { LEVEL, MAT, SAND, WATER, EMPTY, CONCRETE } from './model.js';

/** h = 0. Turns A* into uniform-cost search. */
function zero() { return 0; }

/**
 * Sand-volume bound.
 *
 * Sand only leaves through an outlet (or by setting into concrete). An outlet action that removes
 * s units costs at least 1 + 4s and removes at most one unit, so with T units of sand left the
 * outlets alone cost at least 4T + ceil(T).
 *
 * With water in the grid, a box of sand can instead be turned into concrete for `penalty`; one
 * concrete box absorbs at most one unit. For penalty >= 5 the bound above still holds; for a
 * cheaper penalty we fall back to T * min(5, penalty).
 */
function volume(model, cells) {
  let t = 0; // half-units of sand
  let water = false;
  for (let i = 0; i < cells.length; i++) {
    const m = MAT[cells[i]];
    if (m === SAND) t += LEVEL[cells[i]];
    else if (m === WATER) water = true;
  }
  if (water && model.concretePenalty < 5) return (t / 2) * Math.max(0, model.concretePenalty);
  return 2 * t + Math.ceil(t / 2);
}

/**
 * Volume + gap bound (sand-only grids).
 *
 * Take an empty box that has sand somewhere above it in the same column. Some of that sand must
 * eventually cross the gate on top of the empty box. The first crossing is either a paid action
 * on that very gate (cost >= 3), or a free ride in a pile collapse — which needs the empty box to
 * hold sand first, and without crossing the gate that can only come from its side gate (cost 1).
 * Either way at least 1 is paid by a non-outlet action that is specific to this box, so every
 * such box adds 1 on top of the volume bound.
 *
 * With water or concrete in the grid the argument no longer holds, so the gap term is dropped.
 */
function gap(model, cells) {
  let gaps = 0;
  for (let col = 0; col < 2; col++) {
    let sandAbove = false;
    for (let i = col; i < cells.length; i += 2) {
      const c = cells[i];
      if (c === EMPTY) { if (sandAbove) gaps++; } else if (MAT[c] === SAND) sandAbove = true;
      else if (MAT[c] === WATER || c === CONCRETE) return volume(model, cells);
    }
  }
  return volume(model, cells) + gaps;
}

export const HEURISTICS = Object.freeze({
  gap: { name: 'Volume + gaps', short: 'h₂', fn: gap, note: 'Sand volume plus one per empty box below sand. Admissible and consistent.' },
  volume: { name: 'Sand volume', short: 'h₁', fn: volume, note: '4T + ⌈T⌉ for T units of sand left. Admissible and consistent.' },
  zero: { name: 'Zero', short: 'h₀', fn: zero, note: 'No information: A* behaves exactly like uniform-cost search.' },
});

// Search algorithms over an abstract problem:
//
//   problem.start        encoded start state (a number)
//   problem.isGoal(s)    goal test
//   problem.succ(s)      array of { a: actionId, s: nextState, c: cost }
//   problem.h(s)         heuristic estimate (only used by the informed algorithms)
//
// Every algorithm returns
//   { found, aborted, cost, path: [{a, s, c}], expanded, generated, maxFrontier, maxMemory, iterations, timeMs }
// where maxMemory is the peak number of states held at once (frontier + explored / tables).

const now = () => (typeof performance !== 'undefined' ? performance.now() : Date.now());

class MinHeap {
  constructor() { this.a = []; }
  get size() { return this.a.length; }
  push(x) {
    const a = this.a;
    let i = a.length;
    a.push(x);
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (!less(x, a[p])) break;
      a[i] = a[p];
      i = p;
    }
    a[i] = x;
  }
  pop() {
    const a = this.a;
    const top = a[0];
    const x = a.pop();
    const n = a.length;
    if (n > 0) {
      let i = 0;
      for (;;) {
        let k = 2 * i + 1;
        if (k >= n) break;
        if (k + 1 < n && less(a[k + 1], a[k])) k++;
        if (!less(a[k], x)) break;
        a[i] = a[k];
        i = k;
      }
      a[i] = x;
    }
    return top;
  }
}
// heap entries: [priority, tieBreak, insertionOrder, state, g]
function less(x, y) {
  return x[0] !== y[0] ? x[0] < y[0] : x[1] !== y[1] ? x[1] < y[1] : x[2] < y[2];
}

function newStats() {
  return { found: false, aborted: false, cost: Infinity, path: [], expanded: 0, generated: 0, maxFrontier: 0, maxMemory: 0, iterations: 1, timeMs: 0 };
}

function pathFromParents(parent, goal) {
  const path = [];
  for (let s = goal, e = parent.get(s); e; s = e[0], e = parent.get(s)) path.push({ a: e[1], s, c: e[2] });
  return path.reverse();
}

function succeed(st, path) {
  st.found = true;
  st.path = path;
  st.cost = path.reduce((sum, e) => sum + e.c, 0);
  return st;
}

// ------------------------------------------------------------ uninformed

/** Breadth-first graph search. Finds a solution with the fewest actions (not the cheapest). */
function bfs(p, o) {
  const st = newStats();
  const parent = new Map([[p.start, null]]);
  if (p.isGoal(p.start)) return succeed(st, []);
  const queue = [p.start];
  let head = 0;
  while (head < queue.length) {
    if (st.expanded >= o.maxExpanded) { st.aborted = true; break; }
    const s = queue[head++];
    st.expanded++;
    for (const e of p.succ(s)) {
      st.generated++;
      if (parent.has(e.s)) continue;
      parent.set(e.s, [s, e.a, e.c]);
      if (p.isGoal(e.s)) {
        st.maxMemory = Math.max(st.maxMemory, parent.size);
        return succeed(st, pathFromParents(parent, e.s));
      }
      queue.push(e.s);
    }
    if (queue.length - head > st.maxFrontier) st.maxFrontier = queue.length - head;
    if (parent.size > st.maxMemory) st.maxMemory = parent.size;
  }
  return st;
}

/** Depth-first graph search. Returns the first solution it runs into. */
function dfs(p, o) {
  const st = newStats();
  const parent = new Map();
  const stack = [[p.start, null]];
  while (stack.length) {
    const [s, via] = stack.pop();
    if (parent.has(s)) continue;
    parent.set(s, via);
    if (p.isGoal(s)) return succeed(st, pathFromParents(parent, s));
    if (st.expanded >= o.maxExpanded) { st.aborted = true; break; }
    st.expanded++;
    const succ = p.succ(s);
    for (let i = succ.length - 1; i >= 0; i--) {
      const e = succ[i];
      st.generated++;
      if (!parent.has(e.s)) stack.push([e.s, [s, e.a, e.c]]);
    }
    if (stack.length > st.maxFrontier) st.maxFrontier = stack.length;
    if (stack.length + parent.size > st.maxMemory) st.maxMemory = stack.length + parent.size;
  }
  return st;
}

/**
 * Iterative-deepening depth-first search. Each iteration keeps a transposition table
 * (state -> largest remaining depth it was searched with); without it the many interleavings of
 * independent moves in the two columns make the search tree explode.
 */
function ids(p, o) {
  const st = newStats();
  st.iterations = 0;
  for (let limit = 0; ; limit++) {
    st.iterations++;
    const seen = new Map();
    const path = [];
    let cutoff = false;
    const visit = (s, left) => {
      if (p.isGoal(s)) return true;
      if (left === 0) { cutoff = true; return false; }
      const prev = seen.get(s);
      if (prev !== undefined && prev >= left) return false;
      seen.set(s, left);
      if (st.expanded >= o.maxExpanded) { st.aborted = true; return false; }
      st.expanded++;
      for (const e of p.succ(s)) {
        st.generated++;
        path.push(e);
        if (visit(e.s, left - 1)) return true;
        path.pop();
        if (st.aborted) return false;
      }
      return false;
    };
    const ok = visit(p.start, limit);
    const mem = seen.size + limit;
    if (mem > st.maxMemory) st.maxMemory = mem;
    if (limit > st.maxFrontier) st.maxFrontier = limit;
    if (ok) return succeed(st, path.slice());
    if (st.aborted || !cutoff) return st;
  }
}

// -------------------------------------------------------------- best-first

/**
 * Shared best-first engine.
 *   ucs:    priority g
 *   greedy: priority h          (never reopens a state)
 *   astar:  priority g + w * h  (reopens on a cheaper path, so any admissible h stays optimal)
 */
function bestFirst(p, o, mode, w = 1) {
  const st = newStats();
  const g = new Map([[p.start, 0]]);
  const parent = new Map([[p.start, null]]);
  const closed = new Set();
  const heap = new MinHeap();
  let order = 0;
  const h0 = mode === 'ucs' ? 0 : p.h(p.start);
  heap.push([mode === 'greedy' ? h0 : w * h0, mode === 'greedy' ? 0 : h0, order++, p.start, 0]);
  while (heap.size) {
    const top = heap.pop();
    const s = top[3];
    const gs = top[4];
    if (mode === 'greedy') {
      if (closed.has(s)) continue;
    } else if (gs > g.get(s)) continue; // stale entry
    closed.add(s);
    if (p.isGoal(s)) return succeed(st, pathFromParents(parent, s));
    if (st.expanded >= o.maxExpanded) { st.aborted = true; break; }
    st.expanded++;
    for (const e of p.succ(s)) {
      st.generated++;
      const ng = gs + e.c;
      const old = g.get(e.s);
      if (mode === 'greedy') {
        if (old !== undefined) continue;
        g.set(e.s, ng);
        parent.set(e.s, [s, e.a, e.c]);
        heap.push([p.h(e.s), ng, order++, e.s, ng]);
      } else {
        if (old !== undefined && old <= ng) continue;
        g.set(e.s, ng);
        parent.set(e.s, [s, e.a, e.c]);
        if (mode === 'ucs') heap.push([ng, 0, order++, e.s, ng]);
        else {
          const h = p.h(e.s);
          heap.push([ng + w * h, h, order++, e.s, ng]);
        }
      }
    }
    if (heap.size > st.maxFrontier) st.maxFrontier = heap.size;
    if (g.size > st.maxMemory) st.maxMemory = g.size;
  }
  if (g.size > st.maxMemory) st.maxMemory = g.size;
  return st;
}

/**
 * IDA*: depth-first contours of increasing f = g + h. As with IDS, a per-iteration transposition
 * table (state -> cheapest g seen) keeps the interleavings under control.
 */
function idastar(p, o) {
  const st = newStats();
  st.iterations = 0;
  let bound = p.h(p.start);
  for (;;) {
    st.iterations++;
    const seen = new Map();
    const path = [];
    let next = Infinity;
    let depth = 0;
    const visit = (s, gs) => {
      const f = gs + p.h(s);
      if (f > bound) { if (f < next) next = f; return false; }
      if (p.isGoal(s)) return true;
      const prev = seen.get(s);
      if (prev !== undefined && prev <= gs) return false;
      seen.set(s, gs);
      if (st.expanded >= o.maxExpanded) { st.aborted = true; return false; }
      st.expanded++;
      if (path.length > depth) depth = path.length;
      for (const e of p.succ(s)) {
        st.generated++;
        path.push(e);
        if (visit(e.s, gs + e.c)) return true;
        path.pop();
        if (st.aborted) return false;
      }
      return false;
    };
    const ok = visit(p.start, 0);
    const mem = seen.size + depth;
    if (mem > st.maxMemory) st.maxMemory = mem;
    if (depth > st.maxFrontier) st.maxFrontier = depth;
    if (ok) return succeed(st, path.slice());
    if (st.aborted || next === Infinity) return st;
    bound = next;
  }
}

// ------------------------------------------------------------------ registry

export const ALGORITHMS = Object.freeze({
  bfs: { name: 'BFS', long: 'Breadth-first search', informed: false, optimal: false, run: (p, o) => bfs(p, o), note: 'Fewest actions, ignores cost.' },
  dfs: { name: 'DFS', long: 'Depth-first search', informed: false, optimal: false, run: (p, o) => dfs(p, o), note: 'First solution found, ignores cost.' },
  ids: { name: 'IDS', long: 'Iterative deepening DFS', informed: false, optimal: false, run: (p, o) => ids(p, o), note: 'Fewest actions with depth-first memory.' },
  ucs: { name: 'UCS', long: 'Uniform-cost search (Dijkstra)', informed: false, optimal: true, run: (p, o) => bestFirst(p, o, 'ucs'), note: 'Cheapest solution, no heuristic.' },
  greedy: { name: 'Greedy', long: 'Greedy best-first search', informed: true, optimal: false, run: (p, o) => bestFirst(p, o, 'greedy'), note: 'Always expands the state that looks closest to the goal.' },
  astar: { name: 'A*', long: 'A* search', informed: true, optimal: true, run: (p, o) => bestFirst(p, o, 'astar', 1), note: 'Cheapest solution, guided by the heuristic.' },
  wastar: { name: 'Weighted A*', long: 'Weighted A* (w = 2)', informed: true, optimal: false, run: (p, o) => bestFirst(p, o, 'astar', o.weight ?? 2), note: 'Faster than A*, cost at most w × optimal.' },
  idastar: { name: 'IDA*', long: 'Iterative deepening A*', informed: true, optimal: true, run: (p, o) => idastar(p, o), note: 'Cheapest solution by depth-first f-contours.' },
});

/**
 * Run one algorithm.
 * @param {keyof ALGORITHMS} id
 * @param {object} problem
 * @param {{maxExpanded?: number, weight?: number}} [opts]
 */
export function search(id, problem, opts = {}) {
  const algo = ALGORITHMS[id];
  if (!algo) throw new RangeError(`unknown algorithm: ${id}`);
  const o = { maxExpanded: 2_000_000, ...opts };
  const t0 = now();
  const result = algo.run(problem, o);
  result.timeMs = now() - t0;
  result.algorithm = id;
  return result;
}

// Glue between the environment model and the search algorithms.

import { HEURISTICS } from './heuristics.js';

/**
 * Build a search problem for one start state. Successors, goal tests and heuristic values are
 * memoised per state, so several algorithms can be compared on the same instance without paying
 * for the physics more than once.
 */
export function makeProblem(model, startCells, heuristic = 'gap') {
  const hf = (HEURISTICS[heuristic] || HEURISTICS.gap).fn;
  const cache = new Map();
  const info = (s) => {
    let n = cache.get(s);
    if (!n) {
      const cells = model.decode(s);
      n = { cells, succ: null, h: -1, goal: model.isGoal(cells) };
      cache.set(s, n);
    }
    return n;
  };
  return {
    model,
    start: model.encode(startCells),
    isGoal: (s) => info(s).goal,
    succ: (s) => {
      const n = info(s);
      if (!n.succ) n.succ = model.successors(n.cells);
      return n.succ;
    },
    h: (s) => {
      const n = info(s);
      if (n.h < 0) n.h = hf(model, n.cells);
      return n.h;
    },
    cells: (s) => info(s).cells,
    /** Expand everything reachable from the start, so later timings measure search only. */
    warm(limit = 2_000_000) {
      const seen = new Set([this.start]);
      const stack = [this.start];
      while (stack.length && seen.size < limit) {
        const s = stack.pop();
        this.h(s);
        for (const e of this.succ(s)) if (!seen.has(e.s)) { seen.add(e.s); stack.push(e.s); }
      }
      return seen.size;
    },
  };
}

/** Summarise a solution path: number of actions and how many are side gates (type b). */
export function describePath(model, path) {
  let sides = 0;
  for (const e of path) if (model.actions[e.a].type === 'b') sides++;
  return { steps: path.length, sides, vertical: path.length - sides };
}

