        algo: v.algo,
        label: v.label,
        long: ALGORITHMS[v.algo].long,
        heuristic: v.h,
        guaranteesOptimal: ALGORITHMS[v.algo].optimal && (!v.h || HEURISTICS[v.h].admissible),
