      };
    });
    return {
      meta: { ...meta, count: this.count, solvable: this.solvable, unsolvable: this.count - this.solvable, trivial: this.trivial },
      optimal: {
        cost: summarize(this.optCost),
        steps: summarize(this.optSteps),
