function environment() {
  if (typeof process !== 'undefined' && process.versions && process.versions.node) {
    return `Node.js ${process.versions.node} (${process.platform} ${process.arch})`;
  }
  if (typeof navigator !== 'undefined') return `Browser: ${navigator.userAgent}`;
  return 'unknown';
}

// --------------------------------------------------------------- analyses

/**
 * Sand-only analysis over the full state space of a rows×2 grid (59,049 states for 5 rows),
 * or over `sample` states drawn uniformly from it.
 * @param {{rows?:number, chain?:string, sample?:number, seed?:number, maxExpanded?:number}} cfg
 * @param {(done:number, total:number, phase:string)=>void} [onProgress]
 */
export function analyzeExhaustive(cfg = {}, onProgress = () => {}) {
  const { rows = 5, chain = 'collapse', sample = 0, seed = 1, maxExpanded = 2_000_000 } = cfg;
  const t0 = now();
  const model = new Sandbox({ rows, chain });
  onProgress(0, 1, 'Building the transition table');
  const table = buildTable(model);
  const solved = solveTable(table);
  const hs = tableHeuristics(table);
  const { N, succ } = table;

  let states;
  if (sample > 0 && sample < N) {
    const rng = seededRng(seed);
    const pick = new Set();
    while (pick.size < sample) pick.add(Math.floor(rng() * N));
    states = [...pick].sort((a, b) => a - b);
  } else {
    states = Array.from({ length: N }, (_, i) => i);
  }

  const isGoal = (s) => s === 0;
  const succOf = (s) => succ[s];
  const zero = () => 0;
  const problems = VARIANTS.map((v) => ({ start: 0, isGoal, succ: succOf, h: v.h ? ((arr) => (s) => arr[s])(hs[v.h]) : zero }));
  const collector = new Collector(VARIANTS);
  let mismatches = 0;

  for (let n = 0; n < states.length; n++) {
    const i = states[n];
    const key = model.encode(table.cellsOf(i));
    const runs = VARIANTS.map((v, k) => {
      const p = problems[k];
      p.start = i;
      const r = search(v.algo, p, { maxExpanded });
      let sides = 0;
      for (const e of r.path) if (model.actions[e.a].type === 'b') sides++;
      return { ...r, path: undefined, steps: r.path.length, sides };
    });
    VARIANTS.forEach((v, k) => {
      if (ALGORITHMS[v.algo].optimal && HEURISTICS[v.h || 'zero'].admissible && runs[k].cost !== solved.opt[i]) mismatches++;
    });
    collector.add({ key, opt: solved.opt[i], steps: solved.steps[i], sides: solved.sides[i], runs });
    if ((n & 255) === 255) onProgress(n + 1, states.length, 'Running the search algorithms');
  }
  onProgress(states.length, states.length, 'Done');

  return collector.result({
    kind: sample > 0 && sample < N ? 'sample' : 'exhaustive',
    variant: 'sand',
    rows, chain, stateSpace: N, seed: sample > 0 && sample < N ? seed : null,
    optimalityMismatches: mismatches,
    environment: environment(),
    generatedAt: new Date().toISOString(),
    wallSeconds: (now() - t0) / 1000,
  });
}

/**
 * Random-instance benchmark for any grid size and for the water variant, where the state space is
 * too large to enumerate. The optimum of each instance is taken from uniform-cost search.
 * @param {{rows?:number, chain?:string, water?:boolean, probs?:object, concretePenalty?:number, count?:number, seed?:number, maxExpanded?:number}} cfg
 */
export function analyzeRandom(cfg = {}, onProgress = () => {}) {
  const { rows = 5, chain = 'collapse', water = false, concretePenalty = 10, count = 500, seed = 1, maxExpanded = 300_000 } = cfg;
  const probs = cfg.probs || (water ? PROBS_WATER : PROBS_SAND);
  const t0 = now();
  const model = new Sandbox({ rows, chain, concretePenalty });
  const rng = seededRng(seed);
  const collector = new Collector(VARIANTS);
  const ucsIndex = VARIANTS.findIndex((v) => v.algo === 'ucs');
  for (let n = 0; n < count; n++) {
    const cells = model.random(probs, rng);
    const base = makeProblem(model, cells, 'gap');
    base.warm(maxExpanded);
    const runs = VARIANTS.map((v) => {
      const r = search(v.algo, base.using(v.h || 'zero'), { maxExpanded });
      const d = describePath(model, r.path);
      return { ...r, path: undefined, steps: d.steps, sides: d.sides };
    });
    const best = runs[ucsIndex];
    collector.add({ key: base.start, opt: best.found ? best.cost : Infinity, steps: best.steps, sides: best.sides, runs });
    if ((n & 7) === 7) onProgress(n + 1, count, 'Running the search algorithms');
  }
  onProgress(count, count, 'Done');
  return collector.result({
    kind: 'random',
    variant: water ? 'water' : 'sand',
    rows, chain, probs, concretePenalty, seed,
    stateSpace: (water ? 6 : 3) ** (rows * 2),
    environment: environment(),
    generatedAt: new Date().toISOString(),
    wallSeconds: (now() - t0) / 1000,
  });
}

