/* Sand Boxes — styles. Colours are tokens; dark mode redefines them. */

:root {
  color-scheme: light;
  --bg: #f5efe3;
  --surface: #fffdf8;
  --surface-2: #f1eadb;
  --ink: #1d1a14;
  --ink-2: #554e42;
  --muted: #8a8273;
  --line: #e1d8c5;
  --line-strong: #c9bea6;
  --accent: #a85f17;
  --accent-soft: #f3dfc3;
  --accent-ink: #ffffff;
  --danger: #b3261e;
  --good: #006300;

  /* board */
  --wall: #4a4234;
  --box: #fbf6ea;
  --sand: #e3b65b;
  --sand-dark: #b98a32;
  --water: #4a9be0;
  --water-dark: #2a78d6;
  --concrete: #8d8f93;
  --concrete-dark: #6b6d72;
  --gate: #a85f17;
  --gate-off: #b9ae98;

  /* charts (validated categorical palette, light steps) */
  --chart-surface: #fffdf8;
  --grid: #e8e0cf;
  --axis: #c3bba8;
  --series-1: #2a78d6;
  --series-2: #eb6834;
  --series-3: #1baf7a;
  --series-4: #eda100;
  --series-5: #e87ba4;
  --series-6: #008300;
  --series-7: #6250d6;
  --series-8: #e34948;

  --radius: 12px;
  --shadow: 0 1px 2px rgba(60, 45, 20, 0.06), 0 6px 20px rgba(60, 45, 20, 0.06);
  --sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --bg: #12100c;
    --surface: #1c1914;
    --surface-2: #26221b;
    --ink: #f1ebdd;
    --ink-2: #c8bfac;
    --muted: #91897a;
    --line: #322d24;
    --line-strong: #4a4336;
    --accent: #e3a550;
    --accent-soft: #3a2c17;
    --accent-ink: #1d1a14;
    --danger: #f2877f;
    --good: #0ca30c;
    --wall: #6f6553;
    --box: #14120e;
    --sand: #d9a94d;
    --sand-dark: #a87b29;
    --water: #3987e5;
    --water-dark: #256abf;
    --concrete: #7c7e83;
    --concrete-dark: #5a5c61;
    --gate: #e3a550;
    --gate-off: #4a4336;
    --chart-surface: #1c1914;
    --grid: #2e2a22;
    --axis: #4a4336;
    --series-1: #3987e5;
    --series-2: #d95926;
    --series-3: #199e70;
    --series-4: #c98500;
    --series-5: #d55181;
    --series-6: #008300;
    --series-7: #9085e9;
    --series-8: #e66767;
    --shadow: 0 1px 2px rgba(0, 0, 0, 0.4);
  }
}
:root[data-theme="dark"] {
  color-scheme: dark;
  --bg: #12100c;
  --surface: #1c1914;
  --surface-2: #26221b;
  --ink: #f1ebdd;
  --ink-2: #c8bfac;
  --muted: #91897a;
  --line: #322d24;
  --line-strong: #4a4336;
  --accent: #e3a550;
  --accent-soft: #3a2c17;
  --accent-ink: #1d1a14;
  --danger: #f2877f;
  --good: #0ca30c;
  --wall: #6f6553;
  --box: #14120e;
  --sand: #d9a94d;
  --sand-dark: #a87b29;
  --water: #3987e5;
  --water-dark: #256abf;
  --concrete: #7c7e83;
  --concrete-dark: #5a5c61;
  --gate: #e3a550;
  --gate-off: #4a4336;
  --chart-surface: #1c1914;
  --grid: #2e2a22;
  --axis: #4a4336;
  --series-1: #3987e5;
  --series-2: #d95926;
  --series-3: #199e70;
  --series-4: #c98500;
  --series-5: #d55181;
  --series-6: #008300;
  --series-7: #9085e9;
  --series-8: #e66767;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.4);
}

* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 15px/1.5 var(--sans);
}
h1, h2, h3, p { margin: 0; }
button, select, input { font: inherit; color: inherit; }
[hidden] { display: none !important; }

/* ---------------------------------------------------------------- header */
.top {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px clamp(16px, 3vw, 32px);
  border-bottom: 1px solid var(--line);
  background: var(--surface);
  flex-wrap: wrap;
}
.brand { display: flex; align-items: center; gap: 12px; margin-right: auto; }
.logo { width: 38px; height: 38px; flex: none; }
.logo-bg { fill: var(--ink); }
.logo-sand { fill: var(--sand); }
.logo-empty { fill: color-mix(in srgb, var(--surface) 22%, var(--ink)); }
.brand h1 { font: 600 22px/1.1 var(--serif); letter-spacing: 0.01em; }
.brand p { color: var(--muted); font-size: 13px; }

.tabs { display: flex; gap: 4px; background: var(--surface-2); padding: 4px; border-radius: 10px; }
.tabs button {
  border: 0; background: transparent; padding: 7px 16px; border-radius: 7px; cursor: pointer; color: var(--ink-2); font-weight: 500;
}
.tabs button[aria-selected="true"] { background: var(--surface); color: var(--ink); box-shadow: var(--shadow); }

main { padding: clamp(12px, 2.4vw, 28px); max-width: 1500px; margin: 0 auto; }
section[role="tabpanel"] { display: grid; gap: 18px; }

.card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 18px;
  box-shadow: var(--shadow);
  min-width: 0;
}
.card h2 { font: 600 17px/1.3 var(--serif); margin-bottom: 12px; }
.card h3 { font-size: 13px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.06em; color: var(--ink-2); margin: 18px 0 8px; }
.sub { color: var(--ink-2); font-size: 13.5px; }
.hint { color: var(--muted); font-size: 12.5px; font-weight: 400; text-transform: none; letter-spacing: 0; }
.note { color: var(--ink-2); font-size: 13px; }
.error { color: var(--danger); font-size: 13px; margin-top: 4px; }

/* ----------------------------------------------------------------- forms */
.field { display: grid; gap: 6px; margin-bottom: 14px; min-width: 0; }
.field.row { grid-template-columns: auto auto 1fr; align-items: center; gap: 10px; }
.field.grow { flex: 1; }
.field.end { align-self: end; display: flex; gap: 8px; }
.label { font-size: 12.5px; font-weight: 600; color: var(--ink-2); }
.inline { display: flex; gap: 6px; }
.inline input { flex: 1; min-width: 0; }

select, input[type="text"], input[type="number"] {
  background: var(--surface);
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  padding: 7px 10px;
  min-height: 36px;
  max-width: 100%;
}
input[type="number"] { width: 84px; }
select:focus-visible, input:focus-visible, button:focus-visible, summary:focus-visible, a:focus-visible {
  outline: 2px solid var(--accent); outline-offset: 2px;
}
#gridText { font-family: var(--mono); font-size: 13px; }

.btn {
  border: 1px solid var(--line-strong); background: var(--surface); border-radius: 8px; padding: 7px 14px; min-height: 36px;
  cursor: pointer; font-weight: 500; text-decoration: none; display: inline-flex; align-items: center; justify-content: center; gap: 6px; white-space: nowrap;
}
.btn:hover { background: var(--surface-2); }
.btn.primary { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
.btn.primary:hover { filter: brightness(1.08); }
.btn.small { padding: 4px 10px; min-height: 30px; font-size: 13px; }
.btn:disabled { opacity: 0.5; cursor: default; filter: none; }
.btn-row { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 14px; }
.icon-btn {
  border: 1px solid var(--line-strong); background: var(--surface); border-radius: 8px; width: 36px; height: 36px; cursor: pointer; font-size: 14px; line-height: 1;
}
.icon-btn:hover { background: var(--surface-2); }
.icon-btn:disabled { opacity: 0.4; cursor: default; }

.segmented { display: grid; grid-auto-flow: column; grid-auto-columns: 1fr; background: var(--surface-2); padding: 3px; border-radius: 9px; }
.segmented button { border: 0; background: transparent; padding: 6px 8px; border-radius: 7px; cursor: pointer; color: var(--ink-2); font-weight: 500; }
.segmented button.on { background: var(--surface); color: var(--ink); box-shadow: var(--shadow); }

.stepper { display: inline-flex; align-items: center; border: 1px solid var(--line-strong); border-radius: 8px; overflow: hidden; }
.stepper button { border: 0; background: var(--surface); width: 34px; height: 34px; cursor: pointer; font-size: 17px; }
.stepper button:hover { background: var(--surface-2); }
.stepper output { min-width: 34px; text-align: center; font-weight: 600; font-variant-numeric: tabular-nums; }

details { border-top: 1px solid var(--line); padding: 10px 0 2px; }
details summary { cursor: pointer; font-weight: 600; font-size: 13.5px; color: var(--ink-2); margin-bottom: 10px; }

.brushes { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.brush {
  border: 1px solid var(--line-strong); background: var(--surface); border-radius: 8px; padding: 6px 4px; cursor: pointer;
  display: grid; justify-items: center; gap: 4px; font-size: 11.5px; color: var(--ink-2);
}
.brush.on { border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent-soft); color: var(--ink); }
.swatch { width: 30px; height: 24px; border-radius: 4px; border: 1.5px solid var(--wall); background: var(--box); position: relative; overflow: hidden; }
.swatch i { position: absolute; left: 0; right: 0; bottom: 0; }
.swatch .sand { background: var(--sand); }
.swatch .water { background: var(--water); }
.swatch .concrete { background: repeating-linear-gradient(45deg, var(--concrete), var(--concrete) 4px, var(--concrete-dark) 4px, var(--concrete-dark) 5px); }

.probs { display: grid; grid-template-columns: 1fr auto; gap: 6px 10px; align-items: center; margin-bottom: 8px; font-size: 13px; }
.probs input { width: 72px; }

/* ------------------------------------------------------------- simulator */
.sim-grid { display: grid; gap: 18px; grid-template-columns: minmax(250px, 300px) minmax(320px, 1fr) minmax(280px, 360px); align-items: start; }
@media (max-width: 1120px) {
  .sim-grid { grid-template-columns: minmax(250px, 300px) 1fr; }
  .sim-grid .solver { grid-column: 1 / -1; }
}
@media (max-width: 720px) {
  .sim-grid { grid-template-columns: 1fr; }
  .sim-grid .board-card { order: -1; }
}

.board-head { display: flex; flex-wrap: wrap; gap: 10px 18px; align-items: center; justify-content: space-between; margin-bottom: 8px; }
.tiles { display: flex; gap: 8px; flex-wrap: wrap; }
.tile { background: var(--surface-2); border-radius: 9px; padding: 6px 12px; min-width: 84px; }
.tile span { display: block; font-size: 11.5px; color: var(--ink-2); }
.tile b { font-size: 20px; font-weight: 650; }
.status { font-size: 13.5px; color: var(--ink-2); min-height: 20px; }
.status.good { color: var(--good); font-weight: 600; }
.status.bad { color: var(--danger); font-weight: 600; }

.board-wrap { position: relative; display: flex; justify-content: center; padding: 6px 0 2px; }
#board { display: block; max-width: 100%; touch-action: manipulation; }
.tip {
  position: absolute; pointer-events: none; background: var(--ink); color: var(--surface); padding: 4px 9px; border-radius: 6px; font-size: 12.5px;
  transform: translate(-50%, -130%); white-space: nowrap; z-index: 2;
}

.player { display: flex; align-items: center; justify-content: center; gap: 6px; margin: 8px 0 14px; flex-wrap: wrap; }
.player .play { min-width: 104px; }
.speed { display: inline-flex; align-items: center; gap: 6px; font-size: 12.5px; color: var(--ink-2); margin-left: 8px; }
.speed select { min-height: 32px; padding: 3px 6px; }

.actions { display: flex; flex-wrap: wrap; gap: 6px; min-height: 34px; }
.act {
  border: 1px solid var(--line-strong); background: var(--surface); border-radius: 999px; padding: 3px 5px 3px 11px; cursor: pointer; font-size: 13px;
  display: inline-flex; align-items: center; gap: 7px;
}
.act:hover, .act.hot { border-color: var(--accent); background: var(--accent-soft); }
.act b { background: var(--surface-2); border-radius: 999px; padding: 0 8px; font-variant-numeric: tabular-nums; font-weight: 600; }
.act.hot b, .act:hover b { background: var(--surface); }
.actions .hint { align-self: center; }

.result { background: var(--surface-2); border-radius: 10px; padding: 12px; margin-bottom: 4px; font-size: 13.5px; }
.result .big { font-size: 24px; font-weight: 650; line-height: 1.15; }
.result .big small { font-size: 13px; font-weight: 500; color: var(--ink-2); }
.result dl { display: grid; grid-template-columns: 1fr auto; gap: 2px 12px; margin: 8px 0 0; }
.result dt { color: var(--ink-2); }
.result dd { margin: 0; text-align: right; font-variant-numeric: tabular-nums; }
.badge { display: inline-block; border-radius: 999px; padding: 1px 9px; font-size: 12px; font-weight: 600; vertical-align: middle; }
.badge.good { background: color-mix(in srgb, var(--good) 16%, transparent); color: var(--good); }
.badge.warn { background: var(--accent-soft); color: var(--accent); }
.badge.bad { background: color-mix(in srgb, var(--danger) 14%, transparent); color: var(--danger); }

.timeline { list-style: none; margin: 0; padding: 0; max-height: 340px; overflow: auto; border: 1px solid var(--line); border-radius: 10px; }
.timeline li {
  display: grid; grid-template-columns: 26px 1fr auto auto; gap: 8px; align-items: center; padding: 6px 10px; cursor: pointer; font-size: 13.5px;
  border-bottom: 1px solid var(--line);
}
.timeline li:last-child { border-bottom: 0; }
.timeline li:hover { background: var(--surface-2); }
.timeline li.done { color: var(--ink-2); }
.timeline li.current { background: var(--accent-soft); color: var(--ink); font-weight: 600; }
.timeline .n { color: var(--muted); font-variant-numeric: tabular-nums; font-size: 12px; }
.timeline .c { font-variant-numeric: tabular-nums; }
.timeline .t { color: var(--muted); font-variant-numeric: tabular-nums; font-size: 12px; min-width: 34px; text-align: right; }
.timeline .kind { display: inline-block; width: 18px; height: 18px; border-radius: 5px; text-align: center; line-height: 18px; font-size: 11px; font-weight: 700; margin-right: 6px; background: var(--surface-2); color: var(--ink-2); }
.timeline .empty { display: block; cursor: default; color: var(--muted); padding: 14px 12px; }
.timeline .empty:hover { background: none; }

/* ---------------------------------------------------------------- tables */
.table-wrap { overflow-x: auto; }
table.data { border-collapse: collapse; width: 100%; font-size: 13.5px; }
table.data th, table.data td { padding: 7px 10px; text-align: left; border-bottom: 1px solid var(--line); white-space: nowrap; }
table.data th { font-size: 12px; color: var(--ink-2); font-weight: 600; position: sticky; top: 0; background: var(--surface); }
table.data td.num, table.data th.num { text-align: right; font-variant-numeric: tabular-nums; }
table.data td.wrap { white-space: normal; min-width: 220px; }
table.data tbody tr.pick { cursor: pointer; }
table.data tbody tr.pick:hover { background: var(--surface-2); }
table.data tr.hl td { background: var(--accent-soft); font-weight: 600; }
table.data.compact th, table.data.compact td { padding: 5px 8px; }
table.data + table.data, .table-wrap + .table-wrap { margin-top: 14px; }

/* -------------------------------------------------------------- analysis */
.filter-row { display: flex; gap: 14px 18px; align-items: end; flex-wrap: wrap; margin-bottom: 10px; }
.filter-row .field { margin-bottom: 0; }
.live-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px 14px; }
.progress { position: relative; height: 22px; background: var(--surface-2); border-radius: 999px; overflow: hidden; margin: 10px 0; }
.progress div { position: absolute; inset: 0 auto 0 0; width: 0; background: var(--accent); opacity: 0.35; transition: width 0.2s; }
.progress span { position: relative; display: block; text-align: center; font-size: 12.5px; line-height: 22px; font-variant-numeric: tabular-nums; }

#analysisBody { display: grid; gap: 18px; }
.stat-row { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 12px; }
.stat { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 14px 16px; box-shadow: var(--shadow); }
.stat span { display: block; font-size: 12.5px; color: var(--ink-2); }
.stat b { display: block; font-size: 28px; font-weight: 650; line-height: 1.2; }
.stat small { color: var(--muted); font-size: 12.5px; }

.chart-grid { display: grid; gap: 18px; grid-template-columns: repeat(2, minmax(0, 1fr)); }
@media (max-width: 980px) { .chart-grid { grid-template-columns: 1fr; } }
.chart-card.wide { grid-column: 1 / -1; }
.chart-head { display: flex; gap: 10px 16px; align-items: start; justify-content: space-between; flex-wrap: wrap; margin-bottom: 6px; }
.chart-head h2 { margin-bottom: 2px; }
.chart-head .controls { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.chart-head select { min-height: 32px; padding: 4px 8px; font-size: 13px; }
.chart { position: relative; width: 100%; }
.chart svg { display: block; width: 100%; height: auto; overflow: visible; }
.chart text { font: 11.5px var(--sans); fill: var(--muted); }
.chart .axis-title { fill: var(--ink-2); font-size: 12px; }
.chart .value-label { fill: var(--ink-2); font-variant-numeric: tabular-nums; }
.chart .cat-label { fill: var(--ink); font-size: 12.5px; }
.chart .gridline { stroke: var(--grid); stroke-width: 1; }
.chart .axisline { stroke: var(--axis); stroke-width: 1; }
.chart .ref { stroke: var(--axis); stroke-width: 1.5; }
.chart .mark { transition: opacity 0.12s; }
.chart .dim .mark:not(.hot) { opacity: 0.35; }
.chart .pickable { cursor: pointer; }
.chart-tip {
  position: absolute; pointer-events: none; z-index: 3; background: var(--ink); color: var(--surface); border-radius: 7px; padding: 6px 10px; font-size: 12.5px; line-height: 1.4;
  white-space: nowrap; transform: translate(-50%, calc(-100% - 10px));
}
.chart-tip b { font-variant-numeric: tabular-nums; }
.legend { display: flex; flex-wrap: wrap; gap: 6px 8px; margin: 4px 0 8px; }
.legend button {
  border: 1px solid var(--line-strong); background: var(--surface); border-radius: 999px; padding: 2px 10px 2px 8px; cursor: pointer; font-size: 12.5px;
  display: inline-flex; align-items: center; gap: 6px; color: var(--ink);
}
.legend button i { width: 10px; height: 10px; border-radius: 50%; display: inline-block; }
.legend button[aria-pressed="false"] { color: var(--muted); }
.legend button[aria-pressed="false"] i { background: transparent !important; box-shadow: inset 0 0 0 1.5px var(--muted); }
.chart-foot { color: var(--ink-2); font-size: 13px; margin-top: 8px; }
.chart-card details { margin-top: 10px; }

/* ----------------------------------------------------------------- rules */
.prose-grid { display: grid; gap: 18px; grid-template-columns: repeat(2, minmax(0, 1fr)); align-items: start; }
.prose-grid .wide { grid-column: 1 / -1; }
@media (max-width: 900px) { .prose-grid { grid-template-columns: 1fr; } }
.prose p, .prose ul { margin: 0 0 12px; }
.prose ul { padding-left: 20px; }
.prose li { margin-bottom: 6px; }
.prose h2:not(:first-child) { margin-top: 26px; }
.prose h3 { margin-top: 16px; }
.gridtext { font: 14px/1.5 var(--mono); background: var(--surface-2); border-radius: 8px; padding: 10px 14px; display: inline-block; margin: 0 0 12px; }

.foot { display: flex; gap: 6px 20px; flex-wrap: wrap; justify-content: space-between; padding: 18px clamp(16px, 3vw, 32px) 28px; color: var(--muted); font-size: 12.5px; max-width: 1500px; margin: 0 auto; }
code { font-family: var(--mono); font-size: 0.92em; background: var(--surface-2); padding: 1px 5px; border-radius: 4px; }

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; }
}

toolUseResult.content:
/* Sand Boxes — styles. Colours are tokens; dark mode redefines them. */

:root {
  color-scheme: light;
  --bg: #f5efe3;
  --surface: #fffdf8;
  --surface-2: #f1eadb;
  --ink: #1d1a14;
  --ink-2: #554e42;
  --muted: #8a8273;
  --line: #e1d8c5;
  --line-strong: #c9bea6;
  --accent: #a85f17;
  --accent-soft: #f3dfc3;
  --accent-ink: #ffffff;
  --danger: #b3261e;
  --good: #006300;

  /* board */
  --wall: #4a4234;
  --box: #fbf6ea;
  --sand: #e3b65b;
  --sand-dark: #b98a32;
  --water: #4a9be0;
  --water-dark: #2a78d6;
  --concrete: #8d8f93;
  --concrete-dark: #6b6d72;
  --gate: #a85f17;
  --gate-off: #b9ae98;

  /* charts (validated categorical palette, light steps) */
  --chart-surface: #fffdf8;
  --grid: #e8e0cf;
  --axis: #c3bba8;
  --series-1: #2a78d6;
  --series-2: #eb6834;
  --series-3: #1baf7a;
  --series-4: #eda100;
  --series-5: #e87ba4;
  --series-6: #008300;
  --series-7: #6250d6;
  --series-8: #e34948;

  --radius: 12px;
  --shadow: 0 1px 2px rgba(60, 45, 20, 0.06), 0 6px 20px rgba(60, 45, 20, 0.06);
  --sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --bg: #12100c;
    --surface: #1c1914;
    --surface-2: #26221b;
    --ink: #f1ebdd;
    --ink-2: #c8bfac;
    --muted: #91897a;
    --line: #322d24;
    --line-strong: #4a4336;
    --accent: #e3a550;
    --accent-soft: #3a2c17;
    --accent-ink: #1d1a14;
    --danger: #f2877f;
    --good: #0ca30c;
    --wall: #6f6553;
    --box: #14120e;
    --sand: #d9a94d;
    --sand-dark: #a87b29;
    --water: #3987e5;
    --water-dark: #256abf;
    --concrete: #7c7e83;
    --concrete-dark: #5a5c61;
    --gate: #e3a550;
    --gate-off: #4a4336;
    --chart-surface: #1c1914;
    --grid: #2e2a22;
    --axis: #4a4336;
    --series-1: #3987e5;
    --series-2: #d95926;
    --series-3: #199e70;
    --series-4: #c98500;
    --series-5: #d55181;
    --series-6: #008300;
    --series-7: #9085e9;
    --series-8: #e66767;
    --shadow: 0 1px 2px rgba(0, 0, 0, 0.4);
  }
}
:root[data-theme="dark"] {
  color-scheme: dark;
  --bg: #12100c;
  --surface: #1c1914;
  --surface-2: #26221b;
  --ink: #f1ebdd;
  --ink-2: #c8bfac;
  --muted: #91897a;
  --line: #322d24;
  --line-strong: #4a4336;
  --accent: #e3a550;
  --accent-soft: #3a2c17;
  --accent-ink: #1d1a14;
  --danger: #f2877f;
  --good: #0ca30c;
  --wall: #6f6553;
  --box: #14120e;
  --sand: #d9a94d;
  --sand-dark: #a87b29;
  --water: #3987e5;
  --water-dark: #256abf;
  --concrete: #7c7e83;
  --concrete-dark: #5a5c61;
  --gate: #e3a550;
  --gate-off: #4a4336;
  --chart-surface: #1c1914;
  --grid: #2e2a22;
  --axis: #4a4336;
  --series-1: #3987e5;
  --series-2: #d95926;
  --series-3: #199e70;
  --series-4: #c98500;
  --series-5: #d55181;
  --series-6: #008300;
  --series-7: #9085e9;
  --series-8: #e66767;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.4);
}

* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 15px/1.5 var(--sans);
}
h1, h2, h3, p { margin: 0; }
button, select, input { font: inherit; color: inherit; }
[hidden] { display: none !important; }

/* ---------------------------------------------------------------- header */
.top {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px clamp(16px, 3vw, 32px);
  border-bottom: 1px solid var(--line);
  background: var(--surface);
  flex-wrap: wrap;
}
.brand { display: flex; align-items: center; gap: 12px; margin-right: auto; }
.logo { width: 38px; height: 38px; flex: none; }
.logo-bg { fill: var(--ink); }
.logo-sand { fill: var(--sand); }
.logo-empty { fill: color-mix(in srgb, var(--surface) 22%, var(--ink)); }
.brand h1 { font: 600 22px/1.1 var(--serif); letter-spacing: 0.01em; }
.brand p { color: var(--muted); font-size: 13px; }

.tabs { display: flex; gap: 4px; background: var(--surface-2); padding: 4px; border-radius: 10px; }
.tabs button {
  border: 0; background: transparent; padding: 7px 16px; border-radius: 7px; cursor: pointer; color: var(--ink-2); font-weight: 500;
}
.tabs button[aria-selected="true"] { background: var(--surface); color: var(--ink); box-shadow: var(--shadow); }

main { padding: clamp(12px, 2.4vw, 28px); max-width: 1500px; margin: 0 auto; }
section[role="tabpanel"] { display: grid; gap: 18px; }

.card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 18px;
  box-shadow: var(--shadow);
  min-width: 0;
}
.card h2 { font: 600 17px/1.3 var(--serif); margin-bottom: 12px; }
.card h3 { font-size: 13px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.06em; color: var(--ink-2); margin: 18px 0 8px; }
.sub { color: var(--ink-2); font-size: 13.5px; }
.hint { color: var(--muted); font-size: 12.5px; font-weight: 400; text-transform: none; letter-spacing: 0; }
.note { color: var(--ink-2); font-size: 13px; }
.error { color: var(--danger); font-size: 13px; margin-top: 4px; }

/* ----------------------------------------------------------------- forms */
.field { display: grid; gap: 6px; margin-bottom: 14px; min-width: 0; }
.field.row { grid-template-columns: auto auto 1fr; align-items: center; gap: 10px; }
.field.grow { flex: 1; }
.field.end { align-self: end; display: flex; gap: 8px; }
.label { font-size: 12.5px; font-weight: 600; color: var(--ink-2); }
.inline { display: flex; gap: 6px; }
.inline input { flex: 1; min-width: 0; }

select, input[type="text"], input[type="number"] {
  background: var(--surface);
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  padding: 7px 10px;
  min-height: 36px;
  max-width: 100%;
}
input[type="number"] { width: 84px; }
select:focus-visible, input:focus-visible, button:focus-visible, summary:focus-visible, a:focus-visible {
  outline: 2px solid var(--accent); outline-offset: 2px;
}
#gridText { font-family: var(--mono); font-size: 13px; }

.btn {
  border: 1px solid var(--line-strong); background: var(--surface); border-radius: 8px; padding: 7px 14px; min-height: 36px;
  cursor: pointer; font-weight: 500; text-decoration: none; display: inline-flex; align-items: center; justify-content: center; gap: 6px; white-space: nowrap;
}
.btn:hover { background: var(--surface-2); }
.btn.primary { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
.btn.primary:hover { filter: brightness(1.08); }
.btn.small { padding: 4px 10px; min-height: 30px; font-size: 13px; }
.btn:disabled { opacity: 0.5; cursor: default; filter: none; }
.btn-row { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 14px; }
.icon-btn {
  border: 1px solid var(--line-strong); background: var(--surface); border-radius: 8px; width: 36px; height: 36px; cursor: pointer; font-size: 14px; line-height: 1;
}
.icon-btn:hover { background: var(--surface-2); }
.icon-btn:disabled { opacity: 0.4; cursor: default; }

.segmented { display: grid; grid-auto-flow: column; grid-auto-columns: 1fr; background: var(--surface-2); padding: 3px; border-radius: 9px; }
.segmented button { border: 0; background: transparent; padding: 6px 8px; border-radius: 7px; cursor: pointer; color: var(--ink-2); font-weight: 500; }
.segmented button.on { background: var(--surface); color: var(--ink); box-shadow: var(--shadow); }

.stepper { display: inline-flex; align-items: center; border: 1px solid var(--line-strong); border-radius: 8px; overflow: hidden; }
.stepper button { border: 0; background: var(--surface); width: 34px; height: 34px; cursor: pointer; font-size: 17px; }
.stepper button:hover { background: var(--surface-2); }
.stepper output { min-width: 34px; text-align: center; font-weight: 600; font-variant-numeric: tabular-nums; }

details { border-top: 1px solid var(--line); padding: 10px 0 2px; }
details summary { cursor: pointer; font-weight: 600; font-size: 13.5px; color: var(--ink-2); margin-bottom: 10px; }

.brushes { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.brush {
  border: 1px solid var(--line-strong); background: var(--surface); border-radius: 8px; padding: 6px 4px; cursor: pointer;
  display: grid; justify-items: center; gap: 4px; font-size: 11.5px; color: var(--ink-2);
}
.brush.on { border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent-soft); color: var(--ink); }
.swatch { width: 30px; height: 24px; border-radius: 4px; border: 1.5px solid var(--wall); background: var(--box); position: relative; overflow: hidden; }
.swatch i { position: absolute; left: 0; right: 0; bottom: 0; }
.swatch .sand { background: var(--sand); }
.swatch .water { background: var(--water); }
.swatch .concrete { background: repeating-linear-gradient(45deg, var(--concrete), var(--concrete) 4px, var(--concrete-dark) 4px, var(--concrete-dark) 5px); }

.probs { display: grid; grid-template-columns: 1fr auto; gap: 6px 10px; align-items: center; margin-bottom: 8px; font-size: 13px; }
.probs input { width: 72px; }

/* ------------------------------------------------------------- simulator */
.sim-grid { display: grid; gap: 18px; grid-template-columns: minmax(250px, 300px) minmax(320px, 1fr) minmax(280px, 360px); align-items: start; }
@media (max-width: 1120px) {
  .sim-grid { grid-template-columns: minmax(250px, 300px) 1fr; }
  .sim-grid .solver { grid-column: 1 / -1; }
}
@media (max-width: 720px) {
  .sim-grid { grid-template-columns: 1fr; }
  .sim-grid .board-card { order: -1; }
}

.board-head { display: flex; flex-wrap: wrap; gap: 10px 18px; align-items: center; justify-content: space-between; margin-bottom: 8px; }
.tiles { display: flex; gap: 8px; flex-wrap: wrap; }
.tile { background: var(--surface-2); border-radius: 9px; padding: 6px 12px; min-width: 84px; }
.tile span { display: block; font-size: 11.5px; color: var(--ink-2); }
.tile b { font-size: 20px; font-weight: 650; }
.status { font-size: 13.5px; color: var(--ink-2); min-height: 20px; }
.status.good { color: var(--good); font-weight: 600; }
.status.bad { color: var(--danger); font-weight: 600; }

.board-wrap { position: relative; display: flex; justify-content: center; padding: 6px 0 2px; }
#board { display: block; max-width: 100%; touch-action: manipulation; }
.tip {
  position: absolute; pointer-events: none; background: var(--ink); color: var(--surface); padding: 4px 9px; border-radius: 6px; font-size: 12.5px;
  transform: translate(-50%, -130%); white-space: nowrap; z-index: 2;
}

.player { display: flex; align-items: center; justify-content: center; gap: 6px; margin: 8px 0 14px; flex-wrap: wrap; }
.player .play { min-width: 104px; }
.speed { display: inline-flex; align-items: center; gap: 6px; font-size: 12.5px; color: var(--ink-2); margin-left: 8px; }
.speed select { min-height: 32px; padding: 3px 6px; }

.actions { display: flex; flex-wrap: wrap; gap: 6px; min-height: 34px; }
.act {
  border: 1px solid var(--line-strong); background: var(--surface); border-radius: 999px; padding: 3px 5px 3px 11px; cursor: pointer; font-size: 13px;
  display: inline-flex; align-items: center; gap: 7px;
}
.act:hover, .act.hot { border-color: var(--accent); background: var(--accent-soft); }
.act b { background: var(--surface-2); border-radius: 999px; padding: 0 8px; font-variant-numeric: tabular-nums; font-weight: 600; }
.act.hot b, .act:hover b { background: var(--surface); }
.actions .hint { align-self: center; }

.result { background: var(--surface-2); border-radius: 10px; padding: 12px; margin-bottom: 4px; font-size: 13.5px; }
.result .big { font-size: 24px; font-weight: 650; line-height: 1.15; }
.result .big small { font-size: 13px; font-weight: 500; color: var(--ink-2); }
.result dl { display: grid; grid-template-columns: 1fr auto; gap: 2px 12px; margin: 8px 0 0; }
.result dt { color: var(--ink-2); }
.result dd { margin: 0; text-align: right; font-variant-numeric: tabular-nums; }
.badge { display: inline-block; border-radius: 999px; padding: 1px 9px; font-size: 12px; font-weight: 600; vertical-align: middle; }
.badge.good { background: color-mix(in srgb, var(--good) 16%, transparent); color: var(--good); }
.badge.warn { background: var(--accent-soft); color: var(--accent); }
.badge.bad { background: color-mix(in srgb, var(--danger) 14%, transparent); color: var(--danger); }

.timeline { list-style: none; margin: 0; padding: 0; max-height: 340px; overflow: auto; border: 1px solid var(--line); border-radius: 10px; }
.timeline li {
  display: grid; grid-template-columns: 26px 1fr auto auto; gap: 8px; align-items: center; padding: 6px 10px; cursor: pointer; font-size: 13.5px;
  border-bottom: 1px solid var(--line);
}
.timeline li:last-child { border-bottom: 0; }
.timeline li:hover { background: var(--surface-2); }
.timeline li.done { color: var(--ink-2); }
.timeline li.current { background: var(--accent-soft); color: var(--ink); font-weight: 600; }
.timeline .n { color: var(--muted); font-variant-numeric: tabular-nums; font-size: 12px; }
.timeline .c { font-variant-numeric: tabular-nums; }
.timeline .t { color: var(--muted); font-variant-numeric: tabular-nums; font-size: 12px; min-width: 34px; text-align: right; }
.timeline .kind { display: inline-block; width: 18px; height: 18px; border-radius: 5px; text-align: center; line-height: 18px; font-size: 11px; font-weight: 700; margin-right: 6px; background: var(--surface-2); color: var(--ink-2); }
.timeline .empty { display: block; cursor: default; color: var(--muted); padding: 14px 12px; }
.timeline .empty:hover { background: none; }

/* ---------------------------------------------------------------- tables */
.table-wrap { overflow-x: auto; }
table.data { border-collapse: collapse; width: 100%; font-size: 13.5px; }
table.data th, table.data td { padding: 7px 10px; text-align: left; border-bottom: 1px solid var(--line); white-space: nowrap; }
table.data th { font-size: 12px; color: var(--ink-2); font-weight: 600; position: sticky; top: 0; background: var(--surface); }
table.data td.num, table.data th.num { text-align: right; font-variant-numeric: tabular-nums; }
table.data td.wrap { white-space: normal; min-width: 220px; }
table.data tbody tr.pick { cursor: pointer; }
table.data tbody tr.pick:hover { background: var(--surface-2); }
table.data tr.hl td { background: var(--accent-soft); font-weight: 600; }
table.data.compact th, table.data.compact td { padding: 5px 8px; }
table.data + table.data, .table-wrap + .table-wrap { margin-top: 14px; }

/* -------------------------------------------------------------- analysis */
.filter-row { display: flex; gap: 14px 18px; align-items: end; flex-wrap: wrap; margin-bottom: 10px; }
.filter-row .field { margin-bottom: 0; }
.live-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px 14px; }
.progress { position: relative; height: 22px; background: var(--surface-2); border-radius: 999px; overflow: hidden; margin: 10px 0; }
.progress div { position: absolute; inset: 0 auto 0 0; width: 0; background: var(--accent); opacity: 0.35; transition: width 0.2s; }
.progress span { position: relative; display: block; text-align: center; font-size: 12.5px; line-height: 22px; font-variant-numeric: tabular-nums; }

#analysisBody { display: grid; gap: 18px; }
.stat-row { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 12px; }
.stat { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 14px 16px; box-shadow: var(--shadow); }
.stat span { display: block; font-size: 12.5px; color: var(--ink-2); }
.stat b { display: block; font-size: 28px; font-weight: 650; line-height: 1.2; }
.stat small { color: var(--muted); font-size: 12.5px; }

.chart-grid { display: grid; gap: 18px; grid-template-columns: repeat(2, minmax(0, 1fr)); }
@media (max-width: 980px) { .chart-grid { grid-template-columns: 1fr; } }
.chart-card.wide { grid-column: 1 / -1; }
.chart-head { display: flex; gap: 10px 16px; align-items: start; justify-content: space-between; flex-wrap: wrap; margin-bottom: 6px; }
.chart-head h2 { margin-bottom: 2px; }
.chart-head .controls { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.chart-head select { min-height: 32px; padding: 4px 8px; font-size: 13px; }
.chart { position: relative; width: 100%; }
.chart svg { display: block; width: 100%; height: auto; overflow: visible; }
.chart text { font: 11.5px var(--sans); fill: var(--muted); }
.chart .axis-title { fill: var(--ink-2); font-size: 12px; }
.chart .value-label { fill: var(--ink-2); font-variant-numeric: tabular-nums; }
.chart .cat-label { fill: var(--ink); font-size: 12.5px; }
.chart .gridline { stroke: var(--grid); stroke-width: 1; }
.chart .axisline { stroke: var(--axis); stroke-width: 1; }
.chart .ref { stroke: var(--axis); stroke-width: 1.5; }
.chart .mark { transition: opacity 0.12s; }
.chart .dim .mark:not(.hot) { opacity: 0.35; }
.chart .pickable { cursor: pointer; }
.chart-tip {
  position: absolute; pointer-events: none; z-index: 3; background: var(--ink); color: var(--surface); border-radius: 7px; padding: 6px 10px; font-size: 12.5px; line-height: 1.4;
  white-space: nowrap; transform: translate(-50%, calc(-100% - 10px));
}
.chart-tip b { font-variant-numeric: tabular-nums; }
.legend { display: flex; flex-wrap: wrap; gap: 6px 8px; margin: 4px 0 8px; }
.legend button {
  border: 1px solid var(--line-strong); background: var(--surface); border-radius: 999px; padding: 2px 10px 2px 8px; cursor: pointer; font-size: 12.5px;
  display: inline-flex; align-items: center; gap: 6px; color: var(--ink);
}
.legend button i { width: 10px; height: 10px; border-radius: 50%; display: inline-block; }
.legend button[aria-pressed="false"] { color: var(--muted); }
.legend button[aria-pressed="false"] i { background: transparent !important; box-shadow: inset 0 0 0 1.5px var(--muted); }
.chart-foot { color: var(--ink-2); font-size: 13px; margin-top: 8px; }
.chart-card details { margin-top: 10px; }

/* ----------------------------------------------------------------- rules */
.prose-grid { display: grid; gap: 18px; grid-template-columns: repeat(2, minmax(0, 1fr)); align-items: start; }
.prose-grid .wide { grid-column: 1 / -1; }
@media (max-width: 900px) { .prose-grid { grid-template-columns: 1fr; } }
.prose p, .prose ul { margin: 0 0 12px; }
.prose ul { padding-left: 20px; }
.prose li { margin-bottom: 6px; }
.prose h2:not(:first-child) { margin-top: 26px; }
.prose h3 { margin-top: 16px; }
.gridtext { font: 14px/1.5 var(--mono); background: var(--surface-2); border-radius: 8px; padding: 10px 14px; display: inline-block; margin: 0 0 12px; }

.foot { display: flex; gap: 6px 20px; flex-wrap: wrap; justify-content: space-between; padding: 18px clamp(16px, 3vw, 32px) 28px; color: var(--muted); font-size: 12.5px; max-width: 1500px; margin: 0 auto; }
code { font-family: var(--mono); font-size: 0.92em; background: var(--surface-2); padding: 1px 5px; border-radius: 4px; }

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; }
}

input.content:
// Canvas view of the grid: draws boxes, sand, water, concrete and gates, animates flows,
// and reports clicks on gates and boxes.

import { LEVEL, MAT, SAND, WATER, SOLID, CONCRETE } from '../core/model.js';

const token = (name) => getComputedStyle(document.documentElement).getPropertyValue(name).trim();
const clamp01 = (x) => (x < 0 ? 0 : x > 1 ? 1 : x);
const ease = (t) => t * t * (3 - 2 * t);
const hash = (n) => {
  const x = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return x - Math.floor(x);
};
const reducedMotion = () => matchMedia('(prefers-reduced-motion: reduce)').matches;

export class Board {
  /**
   * @param {HTMLCanvasElement} canvas
   * @param {HTMLElement} wrap      positioned container (used for sizing and the tooltip)
   * @param {HTMLElement} tip       tooltip element inside `wrap`
   * @param {{onGate:(id:number)=>void, onCell:(index:number)=>void, onHover?:(id:number|null)=>void}} handlers
   */
  constructor(canvas, wrap, tip, handlers) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.wrap = wrap;
    this.tip = tip;
    this.handlers = handlers;
    this.model = null;
    this.cells = null;
    this.available = new Map();
    this.hover = null;
    this.highlight = null;
    this.animToken = 0;
    this.busy = false;
    this.readTheme();

    canvas.addEventListener('pointermove', (e) => this.#pointer(e));
    canvas.addEventListener('pointerleave', () => this.#setHover(null));
    canvas.addEventListener('click', (e) => this.#click(e));
    new ResizeObserver(() => { if (this.model) { this.layout(); this.draw(); } }).observe(wrap);
  }

  readTheme() {
    this.colors = {
      wall: token('--wall'), box: token('--box'), sand: token('--sand'), sandDark: token('--sand-dark'),
      water: token('--water'), waterDark: token('--water-dark'), concrete: token('--concrete'), concreteDark: token('--concrete-dark'),
      gate: token('--gate'), gateOff: token('--gate-off'), ink: token('--ink'), muted: token('--muted'), surface: token('--surface'),
    };
    this.patterns = {
      sand: this.#speckle(this.colors.sand, this.colors.sandDark, 90),
      concrete: this.#bricks(this.colors.concrete, this.colors.concreteDark),
    };
    if (this.model) this.draw();
  }

  #speckle(base, dark, n) {
    const c = document.createElement('canvas');
    c.width = c.height = 64;
    const g = c.getContext('2d');
    g.fillStyle = base;
    g.fillRect(0, 0, 64, 64);
    for (let i = 0; i < n; i++) {
      g.globalAlpha = 0.25 + hash(i * 3.1) * 0.5;
      g.fillStyle = hash(i * 5.3) > 0.35 ? dark : '#ffffff';
      g.beginPath();
      g.arc(hash(i) * 64, hash(i + 77.7) * 64, 0.6 + hash(i * 9.9) * 0.9, 0, 6.3);
      g.fill();
    }
    return this.ctx.createPattern(c, 'repeat');
  }

  #bricks(base, dark) {
    const c = document.createElement('canvas');
    c.width = 28;
    c.height = 20;
    const g = c.getContext('2d');
    g.fillStyle = base;
    g.fillRect(0, 0, 28, 20);
    g.strokeStyle = dark;
    g.lineWidth = 1.5;
    g.beginPath();
    g.moveTo(0, 0.75); g.lineTo(28, 0.75);
    g.moveTo(0, 10.75); g.lineTo(28, 10.75);
    g.moveTo(7, 0); g.lineTo(7, 10);
    g.moveTo(21, 10); g.lineTo(21, 20);
    g.stroke();
    return this.ctx.createPattern(c, 'repeat');
  }

  setModel(model) {
    this.model = model;
    this.cancel();
    this.layout();
  }

  /** Recompute geometry for the current model and container width. */
  layout() {
    const rows = this.model.rows;
    const avail = Math.max(250, this.wrap.clientWidth);
    const wall = 8;
    const padX = 30;
    const padT = 8;
    const tray = 34;
    let cellH = Math.max(44, Math.min(92, Math.floor(500 / rows)));
    const cellW = Math.max(70, Math.min(156, Math.round(cellH * 1.7), Math.floor((avail - 2 * padX - 3 * wall) / 2)));
    cellH = Math.min(cellH, Math.round(cellW * 0.8));
    const W = 2 * padX + 2 * cellW + 3 * wall;
    const H = padT + rows * cellH + (rows + 1) * wall + tray;
    this.geo = { rows, wall, padX, padT, tray, cellW, cellH, W, H };

    const dpr = window.devicePixelRatio || 1;
    this.canvas.width = Math.round(W * dpr);
    this.canvas.height = Math.round(H * dpr);
    this.canvas.style.width = `${W}px`;
    this.canvas.style.height = `${H}px`;
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    this.cellRects = [];
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < 2; c++) {
        this.cellRects.push({ x: padX + wall + c * (cellW + wall), y: padT + wall + r * (cellH + wall), w: cellW, h: cellH });
      }
    }
    this.gateRects = this.model.actions.map((a) => {
      if (a.type === 'b') {
        const cell = this.cellRects[a.row * 2];
        const gh = cellH * 0.5;
        return { x: cell.x + cellW, y: cell.y + cellH / 2 - gh / 2, w: wall, h: gh, vertical: false };
      }
      const cell = this.cellRects[a.row * 2 + a.col];
      const gw = cellW * 0.44;
      return { x: cell.x + cellW / 2 - gw / 2, y: cell.y + cellH, w: gw, h: wall, vertical: true };
    });
  }

  /** Show a state without animation. */
  show(cells) {
    this.cancel();
    this.cells = cells;
    this.draw();
  }

  /** Map of action id -> cost for the gates that would move something. */
  setAvailable(map) {
    this.available = map;
    this.draw();
  }

  setHighlight(id) {
    this.highlight = id;
    if (!this.busy) this.draw();
  }

  cancel() {
    this.animToken++;
    this.busy = false;
  }

  /**
   * Animate the elementary flows of one action.
   * @returns {Promise<boolean>} false if the animation was cancelled
   */
  async animate(before, events, speed = 1) {
    const my = ++this.animToken;
    this.busy = true;
    const final = events.length ? events[events.length - 1].cells : before;
    if (reducedMotion()) {
      await this.#tween(160 / speed, my, () => {});
    } else {
      let prev = before;
      for (const ev of events) {
        const gate = this.#gateOf(ev);
        const flowMs = (ev.chain ? 300 : 460) / speed;
        await this.#tween(130 / speed, my, (t) => this.draw(prev, { ev, prev, gate, open: ease(t), flow: 0 }));
        await this.#tween(flowMs, my, (t) => this.draw(prev, { ev, prev, gate, open: 1, flow: t }));
        await this.#tween(110 / speed, my, (t) => this.draw(ev.cells, { ev, prev, gate, open: 1 - ease(t), flow: 1 }));
        if (my !== this.animToken) return false;
        prev = ev.cells;
      }
    }
    if (my !== this.animToken) return false;
    this.busy = false;
    this.cells = final;
    this.draw();
    return true;
  }

  #gateOf(ev) {
    if (ev.kind === 'side') return this.model.sideAction(ev.from >> 1);
    return this.model.verticalAction(ev.from & 1, ev.from >> 1);
  }

  #tween(ms, my, frame) {
    return new Promise((resolve) => {
      const t0 = performance.now();
      const step = (now) => {
        if (my !== this.animToken) return resolve(false);
        const t = ms <= 0 ? 1 : clamp01((now - t0) / ms);
        frame(t);
        if (t < 1) requestAnimationFrame(step); else resolve(true);
      };
      requestAnimationFrame(step);
    });
  }

  // ------------------------------------------------------------------ drawing

  draw(cells = this.cells, overlay = null) {
    if (!cells || !this.geo) return;
    const { ctx, geo, colors } = this;
    const { wall, padX, padT, cellW, cellH, rows, W, H } = geo;
    const now = performance.now();
    ctx.clearRect(0, 0, W, H);

    // frame
    ctx.fillStyle = colors.wall;
    this.#roundRect(padX, padT, 2 * cellW + 3 * wall, rows * cellH + (rows + 1) * wall, 9);
    ctx.fill();

    // boxes and their content
    for (let i = 0; i < cells.length; i++) {
      const rect = this.cellRects[i];
      ctx.fillStyle = colors.box;
      this.#roundRect(rect.x, rect.y, rect.w, rect.h, 3);
      ctx.fill();
      ctx.save();
      ctx.beginPath();
      ctx.rect(rect.x, rect.y, rect.w, rect.h);
      ctx.clip();
      if (overlay && i === overlay.ev.from) {
        const a = LEVEL[overlay.prev[i]];
        const b = LEVEL[overlay.ev.cells[i]];
        this.#fill(rect, MAT[overlay.prev[i]], a + (b - a) * ease(overlay.flow), 1, now);
      } else if (overlay && i === overlay.ev.to) {
        const before = overlay.prev[i];
        const after = overlay.ev.cells[i];
        if (overlay.ev.concrete) {
          this.#fill(rect, MAT[before], LEVEL[before], 1, now);
          this.#fill(rect, SOLID, 2, clamp01((overlay.flow - 0.5) / 0.5), now);
        } else {
          const a = LEVEL[before];
          const b = LEVEL[after];
          this.#fill(rect, overlay.ev.mat, a + (b - a) * ease(overlay.flow), 1, now);
        }
      } else {
        this.#fill(rect, MAT[cells[i]], LEVEL[cells[i]], 1, 0);
      }
      ctx.restore();
      this.#levelLabel(rect, overlay && (i === overlay.ev.from || i === overlay.ev.to) && overlay.flow < 1 ? overlay.prev[i] : cells[i]);
    }

    // gates
    for (let id = 0; id < this.gateRects.length; id++) {
      const open = overlay && overlay.gate === id ? overlay.open : 0;
      const dir = overlay && overlay.gate === id && overlay.ev.kind === 'side' ? (overlay.ev.to > overlay.ev.from ? 1 : -1) : 1;
      this.#gate(id, open, dir);
    }

    // row numbers and outlet marks
    ctx.fillStyle = colors.muted;
    ctx.font = '600 11.5px system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    for (let r = 0; r < rows; r++) ctx.fillText(String(r + 1), padX / 2, this.cellRects[r * 2].y + cellH / 2);
    ctx.strokeStyle = colors.muted;
    ctx.lineWidth = 1.5;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    for (let c = 0; c < 2; c++) {
      const g = this.gateRects[this.model.verticalAction(c, rows - 1)];
      const cx = g.x + g.w / 2;
      const y = g.y + wall + 12;
      ctx.beginPath();
      ctx.moveTo(cx - 6, y); ctx.lineTo(cx, y + 6); ctx.lineTo(cx + 6, y);
      ctx.moveTo(cx - 6, y + 8); ctx.lineTo(cx, y + 14); ctx.lineTo(cx + 6, y + 8);
      ctx.globalAlpha = 0.6;
      ctx.stroke();
      ctx.globalAlpha = 1;
    }

    if (overlay && overlay.flow > 0 && overlay.flow < 1) this.#particles(overlay, now);
  }

  #roundRect(x, y, w, h, r) {
    const ctx = this.ctx;
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, r);
  }

  #fill(rect, mat, level, alpha, time) {
    if (level <= 0 || alpha <= 0 || mat === 0) return;
    const { ctx, colors } = this;
    const h = (level / 2) * rect.h;
    const top = rect.y + rect.h - h;
    ctx.globalAlpha = alpha;
    if (mat === SOLID) {
      ctx.fillStyle = this.patterns.concrete;
      ctx.fillRect(rect.x, rect.y, rect.w, rect.h);
    } else if (mat === SAND) {
      const bump = level >= 2 ? 0 : 4;
      ctx.beginPath();
      ctx.moveTo(rect.x, rect.y + rect.h);
      ctx.lineTo(rect.x, top + bump);
      ctx.quadraticCurveTo(rect.x + rect.w / 2, top - bump, rect.x + rect.w, top + bump);
      ctx.lineTo(rect.x + rect.w, rect.y + rect.h);
      ctx.closePath();
      ctx.fillStyle = this.patterns.sand;
      ctx.fill();
      if (bump) {
        ctx.strokeStyle = colors.sandDark;
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(rect.x, top + bump);
        ctx.quadraticCurveTo(rect.x + rect.w / 2, top - bump, rect.x + rect.w, top + bump);
        ctx.stroke();
      }
    } else if (mat === WATER) {
      const amp = level >= 2 ? 0 : 2.2;
      const phase = time / 260;
      ctx.beginPath();
      ctx.moveTo(rect.x, rect.y + rect.h);
      for (let k = 0; k <= 12; k++) {
        const x = rect.x + (rect.w * k) / 12;
        ctx.lineTo(x, top + Math.sin(phase + k * 1.1) * amp);
      }
      ctx.lineTo(rect.x + rect.w, rect.y + rect.h);
      ctx.closePath();
      ctx.fillStyle = colors.water;
      ctx.globalAlpha = alpha * 0.85;
      ctx.fill();
      ctx.globalAlpha = alpha * 0.35;
      ctx.fillStyle = colors.waterDark;
      ctx.fillRect(rect.x, top + h * 0.55, rect.w, h * 0.45);
    }
    ctx.globalAlpha = 1;
  }

  #levelLabel(rect, code) {
    if (code === 0) return;
    const { ctx, colors } = this;
    const text = code === CONCRETE ? 'concrete' : `${LEVEL[code] === 2 ? '1' : '½'}${MAT[code] === WATER ? ' water' : ''}`;
    ctx.font = '600 11.5px system-ui, sans-serif';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    const w = ctx.measureText(text).width + 10;
    ctx.globalAlpha = 0.82;
    ctx.fillStyle = colors.surface;
    this.#roundRect(rect.x + 5, rect.y + 5, w, 17, 5);
    ctx.fill();
    ctx.globalAlpha = 1;
    ctx.fillStyle = colors.ink;
    ctx.fillText(text, rect.x + 10, rect.y + 8);
  }

  #gate(id, open, dir) {
    const { ctx, colors, geo } = this;
    const g = this.gateRects[id];
    const enabled = this.available.has(id);
    const hot = !this.busy && enabled && (this.hover === id || this.highlight === id);
    const color = enabled || open > 0 ? colors.gate : colors.gateOff;
    // the opening itself
    ctx.fillStyle = colors.box;
    ctx.fillRect(g.x, g.y, g.w, g.h);
    ctx.strokeStyle = color;
    ctx.lineCap = 'round';
    ctx.lineWidth = hot ? 6 : 4;
    const angle = open * 1.35;
    ctx.beginPath();
    if (g.vertical) {
      const y = g.y + g.h / 2;
      const half = g.w / 2 - 1;
      ctx.moveTo(g.x, y);
      ctx.lineTo(g.x + Math.cos(angle) * half, y + Math.sin(angle) * half);
      ctx.moveTo(g.x + g.w, y);
      ctx.lineTo(g.x + g.w - Math.cos(angle) * half, y + Math.sin(angle) * half);
    } else {
      const x = g.x + g.w / 2;
      const half = g.h / 2 - 1;
      ctx.moveTo(x, g.y);
      ctx.lineTo(x + dir * Math.sin(angle) * half, g.y + Math.cos(angle) * half);
      ctx.moveTo(x, g.y + g.h);
      ctx.lineTo(x + dir * Math.sin(angle) * half, g.y + g.h - Math.cos(angle) * half);
    }
    ctx.stroke();
    if (hot) {
      ctx.globalAlpha = 0.22;
      ctx.fillStyle = colors.gate;
      const pad = 7;
      this.#roundRect(g.x - pad, g.y - pad, g.w + 2 * pad, g.h + 2 * pad, 8);
      ctx.fill();
      ctx.globalAlpha = 1;
    }
    void geo;
  }

  #particles(overlay, now) {
    const { ctx, colors, geo } = this;
    const ev = overlay.ev;
    const g = this.gateRects[overlay.gate];
    ctx.fillStyle = ev.mat === WATER ? colors.water : colors.sandDark;
    const n = 30;
    const fade = Math.min(1, overlay.flow * 6, (1 - overlay.flow) * 6);
    for (let k = 0; k < n; k++) {
      const u = (hash(k) + now * 0.0021) % 1;
      const jitter = hash(k + 40.5) - 0.5;
      let x;
      let y;
      if (ev.kind === 'side') {
        const dir = ev.to > ev.from ? 1 : -1;
        const dest = this.cellRects[ev.to];
        const y0 = g.y + g.h / 2 + jitter * g.h * 0.5;
        const floor = dest.y + dest.h - (LEVEL[overlay.prev[ev.to]] / 2) * dest.h;
        x = g.x + g.w / 2 + dir * u * geo.cellW * 0.42;
        y = y0 + u * u * Math.max(0, floor - y0);
      } else {
        const y0 = g.y;
        let y1;
        if (ev.to < 0) y1 = g.y + geo.wall + geo.tray;
        else {
          const dest = this.cellRects[ev.to];
          y1 = dest.y + dest.h - (LEVEL[overlay.prev[ev.to]] / 2) * dest.h;
        }
        x = g.x + g.w / 2 + jitter * g.w * 0.6;
        y = y0 + u * u * (y1 - y0);
      }
      ctx.globalAlpha = fade * (0.55 + hash(k + 9.1) * 0.45);
      ctx.beginPath();
      ctx.arc(x, y, 1.5 + hash(k + 3.3) * 1.3, 0, 6.3);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  // -------------------------------------------------------------- interaction

  #locate(e) {
    const box = this.canvas.getBoundingClientRect();
    const sx = this.geo.W / box.width;
    const x = (e.clientX - box.left) * sx;
    const y = (e.clientY - box.top) * sx;
    const pad = 9;
    for (let id = 0; id < this.gateRects.length; id++) {
      const g = this.gateRects[id];
      if (x >= g.x - pad && x <= g.x + g.w + pad && y >= g.y - pad && y <= g.y + g.h + pad) return { gate: id, x, y };
    }
    for (let i = 0; i < this.cellRects.length; i++) {
      const c = this.cellRects[i];
      if (x >= c.x && x <= c.x + c.w && y >= c.y && y <= c.y + c.h) return { cell: i, x, y };
    }
    return { x, y };
  }

  #pointer(e) {
    if (!this.geo) return;
    const hit = this.#locate(e);
    this.#setHover(hit.gate ?? null);
    this.canvas.style.cursor = hit.gate !== undefined ? (this.available.has(hit.gate) ? 'pointer' : 'not-allowed') : hit.cell !== undefined ? 'cell' : 'default';
    if (hit.gate !== undefined) {
      const act = this.model.actions[hit.gate];
      const cost = this.available.get(hit.gate);
      this.tip.textContent = cost === undefined ? `${act.label} — nothing would move` : `${act.label} — cost ${cost}`;
      const g = this.gateRects[hit.gate];
      const scale = this.canvas.getBoundingClientRect().width / this.geo.W;
      this.tip.style.left = `${this.canvas.offsetLeft + (g.x + g.w / 2) * scale}px`;
      this.tip.style.top = `${this.canvas.offsetTop + g.y * scale}px`;
      this.tip.hidden = false;
    } else {
      this.tip.hidden = true;
    }
  }

  #setHover(id) {
    if (id === null) this.tip.hidden = true;
    if (this.hover === id) return;
    this.hover = id;
    this.handlers.onHover?.(id);
    if (!this.busy) this.draw();
  }

  #click(e) {
    const hit = this.#locate(e);
    if (hit.gate !== undefined) {
      if (this.available.has(hit.gate)) this.handlers.onGate(hit.gate);
    } else if (hit.cell !== undefined) {
      this.handlers.onCell(hit.cell);
    }
  }
}

