    s += `<line x1="${m.l}" x2="${x(r.value)}" y1="${cy}" y2="${cy}" stroke="${C.blue}" stroke-opacity="0.35" stroke-width="2"/>`;
    s += `<circle cx="${x(r.value)}" cy="${cy}" r="5.5" fill="${C.blue}" stroke="${C.bg}" stroke-width="2"/>`;
